"""Migrated Meridian CRM 4.2 ACC-004 credit-hold release guard."""

from decimal import Decimal
from typing import Any


class BusinessRuleViolation(Exception):
    """Legacy business-rule validation failure."""

    code: str
    message: str

    def __init__(self, code: str, message: str) -> None:
        self.code = code
        self.message = message
        super().__init__(message)


def _legacy_numeric(value: Any) -> Decimal:
    """Apply Meridian numeric-context coercion for empty values."""
    if value is None or value == "":
        return Decimal("0")
    return Decimal(str(value))


def release_credit_hold(account: dict) -> tuple[dict, list[dict]]:
    """
    Release an account credit hold under legacy ACC-004 validation semantics.

    The input account is not mutated.
    """
    updated_account = account.copy()

    # A release only represents the legacy Y -> N transition.
    if account.get("CRED_HOLD", "") != "Y":
        return updated_account, []

    if _legacy_numeric(account.get("CRED_LIMIT", "")) <= Decimal("0"):
        raise BusinessRuleViolation(
            code="E1004",
            message="Cannot release credit hold with zero credit limit",
        )

    updated_account["CRED_HOLD"] = "N"
    return updated_account, [
        {
            "code": "CRED_HOLD_OFF",
            "entity_id": account.get("ACCT_ID", ""),
        }
    ]
